# 20-nvdec-deploy  —  deploy nvdec-probe to the TV and run the SAFE layers.
# Read-only: discovers muse-server's decoder fd and opens a SEPARATE handle to
# query capabilities + pixel formats. Touches muse-server's own instance NOT at
# all. Safe to run whether or not an episode is playing (play one for Layer 0 to
# show the live fd). Leaves the binary at /tmp/nvdec-probe (tmpfs, until reboot).
set -e
cat > /tmp/nvdec-probe.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/nvdec-probe.b64 > /tmp/nvdec-probe
chmod +x /tmp/nvdec-probe
rm -f /tmp/nvdec-probe.b64
echo "deployed $(wc -c < /tmp/nvdec-probe) bytes to /tmp/nvdec-probe"
echo "----------------------------------------------------------------"
/tmp/nvdec-probe
